package com.campusconnect.service;
import com.campusconnect.dao.EventDAO; import com.campusconnect.model.*; import com.campusconnect.util.ValidationUtil; import java.util.*;
public class EventService { private final EventDAO dao=new EventDAO(); public List<Event> upcoming(){return dao.findUpcoming();} public List<Event> all(){return dao.findAll();} public void save(Event e,boolean update){ValidationUtil.required(e.getName(),"Event name");ValidationUtil.required(e.getDescription(),"Description");ValidationUtil.required(e.getVenue(),"Venue");ValidationUtil.required(e.getOrganizer(),"Organizer");if(e.getDate()==null||e.getTime()==null)throw new IllegalArgumentException("Date and time are required.");ValidationUtil.positive(e.getCapacity(),"Capacity");if(update&&e.getCapacity()<e.getRegisteredCount())throw new IllegalArgumentException("Capacity cannot be below current registrations.");if(update)dao.update(e);else dao.insert(e);} public void delete(int id){dao.delete(id);} public void register(int eid,int sid){dao.register(eid,sid);} public void cancel(int eid,int sid){dao.cancel(eid,sid);} public List<EventRegistration> registrations(int sid){return dao.registrationsForStudent(sid);} public List<EventRegistration> eventRegistrations(int eid){return dao.registrationsForEvent(eid);} public int totalRegistrations(){return dao.registrations();} }
